mapper.delete:
DELETE FROM user_follows
WHERE follower_id = #{followerId}
  AND following_id = #{followingId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM user_follows
    WHERE follower_id = #{followerId}
      AND following_id = #{followingId}
)

SELECT COUNT(*)
FROM user_follows
WHERE following_id = #{followingId}
